) values (
  '0a237d4f-9ff1-496e-aae4-83b153770acd', 'CSCO-AID-ENT-001', 'ai-defense-enterprise', 'Cisco AI Defense — 엔터프라이즈 AI 개발과 사용을 함께 보호', 'Cisco AI Defense for building and using enterprise AI',
  'public_announcement', 'primary_source', '2025년 1월 15일 Cisco 뉴스룸 발표와 제품 설명을 요약한 기록입니다. 특정 고객의 도입 성과는 포함하지 않았습니다.', 'published', 'public',
  'Cisco AI Defense는 기업이 AI 애플리케이션을 만들고, 배포하고, 쓰는 과정을 한 세트의 안전·보안 통제로 다루겠다고 2025년 1월에 공개한 솔루션입니다. 섀도 AI 발견, 모형 검증, 런타임 보호, 임직원 접근 통제, 기밀 유출 방지가 핵심입니다. 이 기록은 발표된 능력을 PM 계획 틀에 옮겨 둔 것이고, 가격과 기간은 계획 밴드입니다.', 'Cisco가 인용한 2024 AI Readiness Index에서 응답 조직의 29%만 비인가 AI 변조를 탐지·예방할 준비가 되었다고 답했다. AI 앱은 다중 모형·다중 클라우드이고, 취약점은 모형과 앱에 나뉘며 소유자는 개발자, 사용자, 벤더로 갈린다. 공개 데이터가 아니라 기업 데이터로 학습하기 시작하면 위험이 커진다. 모형마다 다른 가드레일로는 통제가 일관되지 않는다.', '네트워크 가시성을 공통 통제 계층으로 쓰면 개발 파이프라인과 임직원 사용을 따로 구매한 포인트 제품에 맡기지 않을 수 있다. 발표문은 2025년 3월부터 기업이 사용할 수 있다고 적었다.', '보안 클라우드 위의 AI 안전 계층으로, 기존 Talos 정보와 Splunk 경보 흐름을 재사용한다.', '보안팀이 AI 자산과 사용자 도구를 한 목록으로 보고, 개발자는 공통 가드레일 위에서 여러 모형을 배포한다. 측정 가능한 고객 절감액은 이 발표에 없다.',
  'cross_industry', '전 산업', 'enterprise', '대기업', 'Global', array['NIST AI RMF', 'OWASP LLM Top 10', 'MITRE'],
  'enterprise', 'hybrid', '하이브리드', 'Security Cloud 안의 AI Defense. 발견, 검증, 런타임, 접근 통제를 네트워크 집행점과 Talos 정보에 연결한다.', 'medium',
  '금액과 기간은 엔터프라이즈 구독 파일럿을 위한 계획 밴드이며 고시 가격이 아닙니다.', 250000, 1200000, 'M',
  4, 8, 8, 16,
  array['Cisco AI Defense', 'Cisco Security Cloud', 'Cisco Talos', 'Splunk'], array['Splunk'], array['섀도 AI 발견', '알고리즘 레드팀', '런타임 검증', '다중 모형 공통 가드레일'], array['접근 통제', '데이터 유출 방지', '프롬프트 인젝션 대응', '서비스 거부 대응'], array['AI Defense', 'AI 디펜스', '섀도 AI', 'shadow AI', '가드레일', '레드팀', '기밀'],
