) values (
  'c6a9af38-c92a-4038-af87-c598f38ee3cc', 'CSCO-HYP-FIN-001', 'hypershield-finance-visibility', '금융권 AI 애플리케이션 가시성과 접근 통제 — Hypershield와 AI Defense', 'Financial-services visibility and access control for AI apps with Hypershield and AI Defense',
  'reference_scenario', 'public_composite', 'Cisco가 공개한 AI Defense와 Hypershield 설명을 금융권 파일럿 계획으로 재구성한 시나리오입니다. 특정 금융사의 도입 실적, 계약 금액, 리드타임을 기록한 것이 아닙니다.', 'published', 'public',
  '금융권 계획 시나리오입니다. 임직원과 개발 조직이 승인되지 않은 AI 애플리케이션을 쓰기 시작하면, 고객정보와 모형 학습 데이터가 어디로 나가는지 보안팀이 보지 못합니다. Cisco AI Defense로 섀도 AI와 승인 AI를 가시화하고 접근을 통제하며, Cisco Hypershield로 데이터센터 안 고가치 워크로드에 분산 익스플로잇 보호와 자율 세그멘테이션을 적용하는 16–28주 파일럿입니다. 금액과 기간은 계획 밴드입니다.', '생성형 AI 요약, 코딩 보조, 외부 SaaS 모형이 현업과 개발망에 먼저 들어옵니다. 기존 보안 스택은 애플리케이션이 어떤 모형을 호출하고 어떤 데이터 소스에 연결되는지, 프롬프트에 기밀이 실리는지 일관되게 보여 주지 못합니다. 동시에 AI 서버와 쿠버네티스 클러스터의 동-서 트래픽은 패치 속도보다 빠르게 늘어, 취약점 공개 이후 완화 통제를 사람이 수작업으로 넣기 어렵습니다.', '네트워크에 이미 있는 관찰점으로 AI 사용과 AI 자산 목록을 만들고, 차단 전에 탐지 모드를 두면 현업 반발을 줄이면서 통제를 올릴 수 있습니다. Hypershield가 공개한 설계는 취약점의 메모리 적재 여부, 실제 악용 여부, 고가치 자산 여부를 따져 수 분 안에 우회 통제를 놓고 패치 후 걷어 내는 흐름입니다. 금융권 파일럿은 그 흐름을 거래 시스템이 아닌 인접 업무부터 검증합니다.', '디지털 금융의 AI 도입 속도와 전자금융 안전성 의무를 같은 프로그램으로 둡니다. 보안 통제가 출시를 막기만 하는 구조에서, 승인된 AI 경로와 금지 데이터 목록을 먼저 제공하는 구조로 바꿉니다.', '파일럿 도메인에서 비인가 AI 앱과 연결 모형을 목록화하고, 기밀 데이터가 승인되지 않은 도구로 나가는 경로에 통제를 겁니다. 고가치 자산의 심각 취약점은 패치를 기다리는 동안 분산 완화 통제의 적용 시간을 측정합니다. 운영 모델과 RACI가 남아 전사 확대의 사업 케이스가 됩니다.',
  'financial_services', '금융', 'enterprise', '대기업 금융', 'APAC', array['전자금융감독규정', '개인정보보호법', '신용정보법', 'NIST AI RMF', 'OWASP LLM Top 10'],
  '5000+', 'hybrid', '하이브리드(온프레미스 데이터센터와 퍼블릭 클라우드)', 'AI Access와 AI Cloud Visibility로 사용자·개발 AI 자산을 보고, 네트워크 계층 런타임 가드레일로 프롬프트 인젝션·유출·서비스 거부를 막으며, Hypershield 분산 집행점으로 데이터센터 세그멘테이션과 익스플로잇 완화를 적용한다. Splunk가 있는 환경이면 AI Defense 경보에 생태계 문맥을 더한다.', 'high',
  '아래 금액·기간·KPI 수치는 계획 밴드와 계획 목표입니다. Cisco 고시 가격도, 특정 고객 실적도 아닙니다. 내부 인건비는 포함하지 않았습니다.', 750000, 2500000, 'L',
  6, 12, 16, 28,
  array['Cisco AI Defense', 'Cisco Hypershield', 'Cisco Security Cloud', 'Cisco Talos', 'Splunk'], array['Splunk'], array['섀도 AI와 승인 AI 발견', '클라우드 AI 자산·데이터 소스 가시성', '알고리즘 레드팀 모형 검증', '런타임 가드레일', 'Talos 기반 자기 최적화 탐지'], array['비인가 AI 접근 통제', '기밀 데이터 유출 방지', '분산 익스플로잇 보호', '자율 세그멘테이션', '무중단 자기 검증 업그레이드'], array['금융권', '금융', '은행', 'Hypershield', '하이퍼실드', 'AI Defense', '가시성', '접근 제어', '접근 통제', '기밀', 'RACI', '섀도 AI', 'shadow AI'],
  array['임직원 AI 애플리케이션 가시성과 승인·비승인 분류', '파일럿 계정계 인접 업무 1개와 개발 샌드박스 1개의 모형·데이터 소스 목록', '금지 데이터 등급이 승인되지 않은 AI로 나가지 않도록 하는 접근 정책과 예외 절차', '고가치 자산 범위의 Hypershield 관측 모드 후 제한적 강제', '프롬프트 인젝션, 민감정보 유출, 모형 서비스 거부 시나리오의 런타임 검증', 'Splunk를 쓰는 경우 경보 연계 설계'], array['전사 모든 자회사와 해외 법인의 일괄 차단', '계정계 원장 트랜잭션 경로의 즉각적 강제 세그멘테이션', '고객 데이터로 기초 모형을 새로 학습하는 작업', '특정 벤더 가격을 이 밴드 숫자로 확정하는 일'], array['파일럿 도메인에서 표본 조사한 AI 앱·모형이 인벤토리와 대조된다.', '비인가 도구로 나가는 금지 데이터 시나리오가 탐지 모드에서 재현되고, 강제 모드에서 차단된다.', '고가치 자산 파일럿 CVE에 대해 완화 통제 적용 시각이 기록된다.', 'RACI와 예외 처리 SLA가 스폰서 승인을 받는다.'], 'expected_planning', array['기대 결과: 승인·비승인 AI의 단일 목록과 소유자', '기대 결과: 네트워크 계층 가드레일과 데이터센터 분산 통제가 같은 운영 리듬으로 돌아감', '공개된 제품 설계 목표: Hypershield는 패치 전 완화 통제를 수 분 단위로 배치하고, 패치 후 제거한다. 이 파일럿은 그 목표를 측정 항목으로 둔다.'],
  null, null, '2025-01-15'
);
