insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'R1', '인벤토리에 로컬·비표준 AI가 빠진다', '브라우저 확장과 개인 단말 도구는 네트워크 관찰만으로 안 잡힐 수 있다.', 'security', 4, 4, 'mitigate', '네트워크 관찰에 IdP 로그와 엔드포인트 표본을 더하고 공백을 이슈로 남긴다.', '공백 도메인은 강제 모드에서 제외하고 별도 조사 차터를 연다.', '정보보호 운영', '표본 대조에서 누락 3건 이상');
insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'R2', '차단 이후 현업이 우회한다', '승인 대안 없이 막으면 개인 계정 SaaS로 데이터가 새 나갈 수 있다.', 'change', 4, 3, 'mitigate', '차단 2주 전에 승인 도구와 예외 SLA를 공지한다.', '우회 급증 시 강제 범위를 축소하고 스폰서에게 보고한다.', '고객 PM', '예외 요청이 주간 처리 용량의 2배');
insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'R3', '가드레일 오탐이 파일럿 업무를 멈춘다', '정상 요약 프롬프트가 유출로 오인될 수 있다.', 'quality', 3, 3, 'mitigate', '최소 2주는 탐지 모드로 두고 오탐률을 보고 강제한다.', '업무 단위로 탐지 모드에 되돌린다.', '정보보호 운영', '핵심 시나리오 오탐률이 계획 목표를 넘음');
insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'R4', '자동 세그멘테이션이 거래 흐름을 끊는다', '동-서 통제가 계정계 인접 호출까지 막을 수 있다.', 'technical', 2, 5, 'mitigate', '거래 경로는 범위 밖으로 고정하고, 관측 모드와 듀얼 데이터 플레인 검증 뒤에만 강제한다.', '해당 정책을 즉시 제거하고 변경 동결을 건다.', '데이터센터 네트워크 아키텍트', '파일럿 외 서비스 오류 티켓');
insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'R5', '규제 해석이 파일럿 중에 바뀐다', '생성형 AI 입력에 대한 감독 해석이 금지 목록을 넓힐 수 있다.', 'compliance', 3, 5, 'mitigate', '금지 목록을 버전 관리하고 준법을 변경 승인자에 둔다.', '새 해석 범위는 확대 차터로 넘기고 파일럿 성공 기준은 유지한다.', '준법·개인정보', '감독 자료 또는 내부 법무 의견 변경');
insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'R6', '조달 리드타임이 실행 창을 민다', '구독과 데이터센터 플랫폼의 도착 시점이 다르다.', 'schedule', 3, 3, 'mitigate', '소프트웨어 가시성 트랙과 데이터센터 통제 트랙의 마일스톤을 분리한다.', '먼저 도착한 트랙만 파일럿 수용 기준에 포함한다.', '조달', '발주 후 2주 안에 납기 미확정');
insert into issues (case_id, issue_code, title, status, owner_role, next_action) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'I1', '파일럿 현업 도메인이 아직 지정되지 않음', 'open', '현업 데이터 오너', '여신 문서 보조와 개발 샌드박스 중 착수 워크숍에서 확정');
insert into issues (case_id, issue_code, title, status, owner_role, next_action) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'I2', '기존 SIEM이 Splunk인지 고객마다 다름', 'open', '정보보호 운영', '연계는 선택 과업으로 유지하고 착수 때 예/아니오로 닫기');
