insert into kpis (case_id, name, baseline, target, unit, method, owner_role, cadence) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', '금지 데이터 유출 시나리오 차단', '미측정', '강제 모드에서 재현 시나리오 차단', '건', '계획 목표. 사전에 적은 시나리오만 센다. 벤더 SLA가 아니다.', '정보보호 운영', '강제 전후');
