insert into decisions (case_id, decision_code, title, choice, rationale, decided_on, owner_role) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'D1', '파일럿 강제 범위', '거래 원장 경로는 제외하고 인접 업무와 개발 샌드박스만 강제한다.', '동-서 통제의 오작용이 고객 거래로 번지지 않게 한다.', null, 'CISO(스폰서)');
insert into decisions (case_id, decision_code, title, choice, rationale, decided_on, owner_role) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'D2', '차단 순서', '가시성, 탐지 모드, 사람 승인, 제한 강제 순서로 간다.', 'AI Defense와 Hypershield 모두 자동 조치를 바로 켜지 않는다.', null, '정보보호 운영');
insert into decisions (case_id, decision_code, title, choice, rationale, decided_on, owner_role) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', 'D3', 'SIEM 연계', 'Splunk가 있으면 경보 연계를 포함하고, 없으면 성공 기준에서 뺀다.', 'Cisco는 Splunk 고객의 AI Defense 경보 보강을 공개했다. 전제 조건이 없는 고객에게 필수로 두지 않는다.', null, '고객 PM');
insert into lessons (case_id, theme, statement, applicability) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', '순서', 'AI 접근 통제는 대안 경로와 예외 SLA가 공지된 뒤에 차단해야 우회가 줄어든다.', '현업이 이미 공개 챗봇을 쓰는 규제 산업');
insert into lessons (case_id, theme, statement, applicability) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', '데이터센터', '분산 익스플로잇 보호의 첫 적용 대상은 고가치이면서 거래 원장이 아닌 자산으로 고른다.', 'Hypershield 관측 모드 도입');
insert into lessons (case_id, theme, statement, applicability) values ('c6a9af38-c92a-4038-af87-c598f38ee3cc', '증거', '수 분 단위 완화는 제품의 공개 설계 목표로 말하고, 파일럿에서 잰 시간만 고객 결과로 말한다.', '제안서와 경영진 보고');
