비즈니스 가치: 파일럿 도메인에서 비인가 AI 앱과 연결 모형을 목록화하고, 기밀 데이터가 승인되지 않은 도구로 나가는 경로에 통제를 겁니다. 고가치 자산의 심각 취약점은 패치를 기다리는 동안 분산 완화 통제의 적용 시간을 측정합니다. 운영 모델과 RACI가 남아 전사 확대의 사업 케이스가 됩니다.', 266, '[0.000000,0.029148,0.000000,0.000000,0.000000,0.029148,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.087445,0.000000,0.000000,0.000000,0.029148,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.043722,0.000000,0.000000,-0.029148,0.043722,0.000000,0.000000,0.000000,0.000000,-0.029148,0.000000,0.000000,0.000000,-0.087445,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.058296,0.000000,0.000000,0.000000,0.000000,-0.043722,0.029148,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043722,0.000000,0.000000,0.043722,-0.262334,0.087445,0.000000,0.000000,0.000000,0.000000,-0.087445,0.000000,0.000000,0.000000,0.000000,0.000000,-0.087445,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.087445,0.029148,0.000000,0.000000,0.000000,0.000000,0.000000,0.029148,0.000000,0.058296,-0.029148,0.000000,0.000000,0.000000,0.000000,0.000000,-0.087445,0.029148,0.000000,0.087445,0.000000,0.145741,0.000000,0.000000,0.000000,0.087445,0.000000,0.000000,0.000000,0.058296,0.000000,0.000000,0.000000,0.000000,0.000000,0.043722,0.000000,0.087445,0.000000,0.000000,0.000000,0.029148,-0.160315,0.000000,-0.218612,0.029148,0.000000,0.000000,0.000000,0.029148,0.000000,0.000000,-0.058296,0.043722,0.000000,0.000000,-0.058296,0.058296,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.029148,0.000000,0.000000,0.058296,0.000000,0.000000,0.000000,0.029148,0.000000,0.000000,0.000000,0.306056,0.000000,0.058296,0.000000,0.058296,-0.262334,0.029148,0.000000,0.000000,0.000000,0.116593,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.058296,0.000000,0.000000,0.000000,-0.058296,0.058296,0.000000,0.000000,0.000000,0.000000,-0.087445,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.145741,0.000000,0.000000,0.0