Hypershield는 2024년 4월에 공개된 AI 규모 데이터센터용 분산 보안이다. 박스형 방화벽 대신 서버, 가상머신, 컨테이너, 네트워크의 많은 집행점에 통제를 둔다. 분산 익스플로잇 보호는 취약점이 메모리에 있는지, 실제로 악용되는지, 고가치 자산인지를 보고 패치 전에 외과적 완화 통제를 두며 패치 후 제거한다. 자율 세그멘테이션은 흐름과 프로세스 행동을 보고 횡적 이동을 줄이는 규칙을 갱신한다. 자기 검증 업그레이드는 듀얼 데이터 플레인에서 고객 트래픽으로 시험한 뒤 무중단으로 넘긴다. 금융 시나리오에서는 이 세 가지를 거래 원장 밖에 먼저 둔다.', 340, '[0.000000,0.047874,0.000000,0.000000,0.000000,0.071811,-0.071811,0.000000,0.000000,0.000000,0.000000,0.047874,0.000000,0.095748,-0.023937,0.047874,0.000000,0.023937,0.000000,0.000000,-0.023937,0.000000,0.000000,0.000000,0.000000,0.047874,0.000000,0.035906,-0.023937,0.023937,-0.023937,0.035906,0.000000,0.023937,0.000000,0.000000,0.000000,0.023937,-0.071811,0.000000,-0.071811,0.023937,0.000000,0.000000,0.000000,0.023937,-0.023937,0.047874,0.000000,0.000000,0.000000,0.000000,-0.035906,0.000000,0.000000,0.047874,0.000000,0.095748,0.000000,0.000000,-0.035906,0.023937,0.000000,0.035906,-0.215434,0.071811,0.000000,0.000000,0.000000,0.023937,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.035906,0.000000,-0.023937,0.000000,0.000000,0.047874,-0.023937,0.000000,-0.047874,0.071811,0.000000,0.047874,0.000000,0.023937,0.000000,0.000000,-0.023937,0.047874,-0.023937,0.000000,0.000000,0.071811,0.000000,0.047874,0.000000,0.095748,0.000000,0.000000,-0.071811,0.071811,0.000000,0.047874,0.000000,0.071811,0.000000,0.000000,-0.095748,0.047874,-0.047874,0.000000,0.000000,0.023937,0.000000,0.035906,0.000000,0.071811,-0.023937,0.071811,0.000000,0.023937,-0.035906,0.000000,-0.179528,0.095748,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.095748,0.107717,0.000000,0.047874,0.000000,0.047874,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.023937,0.000000,0.119685,0.000000,0.023937,0.000000,0.000000,0.000000,0.023937,0.000000,0.251339,0.000000,0.119685,0.000000,0.000000,-0.191497,0.047874,-0.023937,0.000000,0.000000,0.023937,0.000000,0.000000,0.000000,0.023937,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.023937,0.000000,0.000000,0