성공 기준
- 파일럿 도메인에서 표본 조사한 AI 앱·모형이 인벤토리와 대조된다.
- 비인가 도구로 나가는 금지 데이터 시나리오가 탐지 모드에서 재현되고, 강제 모드에서 차단된다.
- 고가치 자산 파일럿 CVE에 대해 완화 통제 적용 시각이 기록된다.
- RACI와 예외 처리 SLA가 스폰서 승인을 받는다.', 269, '[0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.155161,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.042317,0.000000,0.000000,0.000000,0.042317,-0.056422,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.056422,0.000000,0.000000,0.000000,0.000000,0.000000,-0.028211,0.056422,0.000000,0.000000,0.000000,0.000000,-0.042317,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.042317,0.000000,0.000000,0.042317,-0.253899,0.084633,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028211,0.000000,0.084633,-0.084633,0.000000,-0.056422,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.282110,-0.028211,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028211,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028211,0.000000,0.000000,0.000000,0.000000,0.000000,0.042317,0.000000,0.141055,0.000000,0.000000,0.000000,0.028211,-0.155161,0.056422,-0.211583,0.028211,0.000000,0.000000,0.000000,0.056422,0.000000,0.000000,0.000000,0.070528,0.000000,0.000000,-0.056422,0.056422,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.056422,0.056422,0.000000,0.084633,0.000000,0.000000,0.000000,0.000000,0.000000,0.296216,0.000000,0.028211,0.000000,0.056422,-0.282110,0.028211,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.056422,0.056422,0.000000,0.000000,0.000000,0.000000,0.000000,0.056422,0.000000,0.000000,0.000000,0.056422,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.084633,0.000000,0.000000,0.000000,0.000000,-0.056422,0.000000,-0.028211,0.000000,0.000000,0.000000,-0.042317,0.028211,0.000000,0.126950,0.000000,0.000000,0.000000,0.0000