insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('cf356884-fecb-4a88-aa53-083918f0552b', 'c6a9af38-c92a-4038-af87-c598f38ee3cc', 12, 'controls', 'KPI·원가·의사결정 (2)', 'case: CSCO-HYP-FIN-001
title: 금융권 AI 애플리케이션 가시성과 접근 통제 — Hypershield와 AI Defense
industry: 금융 (financial_services)
segment: 대기업 금융
solutions: Cisco AI Defense, Cisco Hypershield, Cisco Security Cloud, Cisco Talos, Splunk
partners: Splunk
aliases: 금융권, 금융, 은행, Hypershield, 하이퍼실드, AI Defense, 가시성, 접근 제어, 접근 통제, 기밀, RACI, 섀도 AI, shadow AI
fidelity: public_composite
원가 계획 밴드
아래 금액·기간·KPI 수치는 계획 밴드와 계획 목표입니다. Cisco 고시 가격도, 특정 고객 실적도 아닙니다. 내부 인건비는 포함하지 않았습니다.
- AI Defense 구독(1차년도) (opex): 180000–450000 USD. 계획 밴드. 사용자 수와 클라우드 계정 수에 따라 움직인다.
- Hypershield 데이터센터 집행 (capex): 400000–1200000 USD. 계획 밴드. 스위치·DPU·소프트웨어 구성은 설계 후에 갈린다.
- 파트너 설계·검증 (opex): 150000–400000 USD. 내부 인력으로 대체하면 낮아진다.
- 운영·현업 교육 (opex): 20000–40000 USD. 런북과 예외 절차 교육.

의사결정
- D1 파일럿 강제 범위: 거래 원장 경로는 제외하고 인접 업무와 개발 샌드박스만 강제한다.. 동-서 통제의 오작용이 고객 거래로 번지지 않게 한다.
- D2 차단 순서: 가시성, 탐지 모드, 사람 승인, 제한 강제 순서로 간다.. AI Defense와 Hypershield 모두 자동 조치를 바로 켜지 않는다.
- D3 SIEM 연계: Splunk가 있으면 경보 연계를 포함하고, 없으면 성공 기준에서 뺀다.. Cisco는 Splunk 고객의 AI Defense 경보 보강을 공개했다. 전제 조건이 없는 고객에게 필수로 두지 않는다.', 522, '[0.000000,0.017426,-0.017426,0.000000,0.000000,0.069705,-0.139410,0.000000,0.000000,0.017426,0.000000,0.104558,0.000000,0.069705,0.000000,0.000000,0.000000,0.069705,0.000000,0.000000,-0.052279,0.069705,0.000000,0.034853,0.000000,0.017426,0.000000,0.026139,0.000000,0.052279,0.000000,0.026139,-0.034853,0.052279,-0.052279,0.000000,-0.026139,0.017426,-0.087131,0.000000,-0.034853,0.017426,0.000000,0.034853,-0.026139,0.226541,0.000000,0.000000,0.000000,0.052279,-0.034853,0.000000,-0.026139,0.000000,-0.034853,0.034853,0.000000,0.000000,0.000000,0.000000,-0.026139,0.017426,0.000000,0.060992,-0.174263,0.104558,0.000000,0.000000,0.000000,0.052279,-0.052279,0.000000,0.000000,0.017426,-0.017426,0.087131,-0.026139,0.052279,0.000000,0.000000,-0.017426,0.069705,-0.034853,0.000000,-0.017426,0.069705,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.017426,0.243968,-0.017426,0.000000,0.000000,0.017426,-0.052279,0.000000,0.000000,0.095844,-0.026139,0.000000,0.000000,0.052279,0.000000,0.000000,0.000000,0.017426,0.000000,0.017426,0.000000,0.017426,-0.052279,0.069705,0.000000,0.017426,-0.017426,0.060992,0.000000,0.069705,0.000000,0.000000,0.000000,0.017426,-0.060992,0.000000,-0.182976,0.017426,-0.017426,0.000000,-0.034853,0.139410,0.000000,0.000000,-0.017426,0.026139,-0.034853,0.000000,-0.017426,0.052279,0.000000,0.034853,0.000000,0.000000,-0.034853,0.000000,0.000000,0.069705,0.000000,0.034853,0.000000,0.034853,0.000000,0.000000,0.000000,0.069705,0.000000,0.235254,0.000000,0.034853,0.000000,0.000000,-0.174263,0.034853,0.000000,0.000000,0.000000,0.052279,-0.017426,0.000000,0.000000,0.000000,0.000000,0.034853,0.000000,0.052279,0.000000,0.000000,-0.034853,0.000000,0.000000,0.034853,0.000000,0.034853,-0.017426,0.000000,0.000000,0.000000,0.000000,0.078418,0.000000,0.034853,0.000000,0.000000,0.000000,0.104558,-0.017426,0.000000,-0.017426,0.000000,-0.05227