insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('5926e49b-a4c3-46f6-af82-e307e20bc3ba', '90161c79-3646-4eb6-a438-a1a0241625b5', 0, 'business_case', '비즈니스 케이스', 'case: CSCO-AIF-NVD-001
title: Cisco Secure AI Factory with NVIDIA — 엔터프라이즈 AI 인프라 파일럿
industry: 기술·인프라 (technology)
segment: 대기업 또는 네오클라우드
solutions: Cisco UCS AI, Cisco Silicon One, Nexus Hyperfabric AI, Cisco AI Defense, Cisco Hypershield
partners: NVIDIA Spectrum-X, NVIDIA AI Enterprise, NVIDIA HGX, NVIDIA MGX, Pure Storage, Hitachi Vantara, NetApp, VAST Data
aliases: AI 팩토리, AI factory, 엔비디아, NVIDIA, Spectrum-X, Silicon One, HGX, 데이터센터, 포드
fidelity: primary_source
Cisco와 NVIDIA는 2025년에 엔터프라이즈가 AI 인프라를 설계·배포·보호하는 참조 아키텍처를 공개했다. 컴퓨팅은 NVIDIA HGX·MGX 기반 Cisco UCS AI 서버, 네트워크는 Silicon One과 Spectrum-X 이더넷 및 Nexus Hyperfabric AI, 스토리지는 인증 파트너, 소프트웨어는 NVIDIA AI Enterprise다. 보안 축에는 Hypershield와 AI Defense가 NVIDIA Enterprise AI Factory 검증 설계에 포함된다고 6월에 발표되었다. 이 사례는 첫 프로덕션 포드를 세우는 PM 계획이다.

문제: AI 학습과 추론은 프론트엔드와 백엔드 네트워크, GPU 간 통신, 스토리지, 보안 정책을 따로 발주하면 운영 모델이 갈라진다. 공개 클라우드만으로는 데이터 위치와 주권 제약을 맞추기 어려운 조직이 있다. 프로토타입에서 운영으로 넘길 공통 아키텍처가 없다.

기회: Cisco는 Spectrum-X에 포함되는 유일한 파트너 실리콘으로 Silicon One을 넣겠다고 2025년 2월에 밝혔다. 3월에는 보안이 중심에 있는 AI 팩토리 참조 구조를, 6월에는 AI POD, 통합 Nexus Dashboard, Silicon One 기반 Spectrum-X 이더넷 시연, 400G BiDi 옵틱을 발표했다. 첫 포드는 이 공개 범위 안에서 규모를 고정하면 된다.

전략 정합: 사내 AI 플랫폼을 실험실 클러스터에서 운영 가능한 포드로 옮기고, 보안과 네트워크 운영을 같은 변경 창으로 묶는다.

비즈니스 가치: 표준 포드 하나로 컴퓨팅·네트워크·스토리지·보안의 책임 경계를 고정한다. 성능 수치는 도입 후 측정 항목으로 두고, 발표문에 있는 고객 절감 시간을 이 사례의 약속으로 쓰지 않는다.', 677, '[-0.082631,0.027544,0.000000,0.013772,-0.013772,0.068859,-0.041315,0.000000,0.000000,0.068859,-0.013772,0.027544,0.000000,0.172148,-0.041315,0.013772,-0.041315,0.068859,-0.013772,0.000000,0.000000,0.179034,-0.027544,0.000000,0.000000,0.041315,0.000000,0.020658,-0.055087,0.027544,0.000000,0.020658,-0.055087,0.000000,-0.041315,0.000000,0.000000,0.075745,-0.144604,0.013772,-0.068859,0.048201,0.000000,0.027544,0.000000,0.013772,0.000000,0.020658,-0.013772,0.041315,-0.027544,0.000000,0.000000,0.027544,-0.013772,0.000000,-0.013772,0.027544,0.000000,0.000000,0.000000,0.013772,0.000000,0.034430,-0.013772,0.000000,-0.061973,0.000000,-0.013772,0.055087,-0.110175,0.000000,-0.013772,0.055087,0.000000,0.000000,-0.027544,0.013772,-0.013772,0.020658,-0.027544,0.096403,0.000000,0.027544,0.000000,0.000000,-0.027544,0.000000,-0.027544,0.068859,0.000000,0.068859,0.000000,0.096403,-0.013772,0.027544,0.000000,0.013772,0.000000,0.075745,0.000000,0.096403,-0.020658,0.041315,0.000000,0.137718,-0.041315,0.000000,-0.034430,0.013772,0.000000,0.103289,-0.013772,0.027544,0.000000,0.068859,0.000000,0.123946,0.000000,0.020658,0.000000,0.055087,0.000000,0.000000,0.000000,0.000000,-0.027544,0.000000,-0.179034,0.041315,0.000000,0.000000,0.000000,0.041315,0.000000,0.103289,0.000000,0.034430,0.000000,0.000000,-0.013772,0.027544,0.000000,0.000000,-0.068859,0.013772,0.000000,0.000000,0.000000,0.144604,0.000000,0.000000,-0.061973,0.110175,0.000000,0.000000,0.000000,0.096403,-0.027544,0.454470,0.000000,0.013772,0.000000,0.000000,0.000000,0.041315,-0.055087,0.000000,0.000000,0.110175,0.000000,0.027544,-0.027544,0.027544,0.000000,0.000000,0.000000,0.082631,0.000000,0.027544,-0.013772,0.041315,0.000000,0.000000,-0.061973,0.000000,0.000000,0.000000,-0.013772,0.041315,0.000000,0.000000,0.000000,0.055087,0.000000,0.000000,-0.041315,0.068859,0.000000,0.055087,0.000000,0.013772,0.000000,0.020658,