2025년 6월 발표는 AI POD 확장, ACI와 NX-OS VXLAN EVPN을 모으는 Unified Nexus Dashboard(7월 릴리스 예정으로 발표), Intelligent Packet Flow, G200 기반 스위치와 NVIDIA NIC의 Spectrum-X 이더넷 통합 시연, 기존 이중 멀티모드 광을 유지하는 400G BiDi, UCS C845A M8의 RTX PRO 6000 Blackwell을 포함한다. 같은 발표에서 AI Defense와 Hypershield가 NVIDIA Enterprise AI Factory 검증 설계에 들어가고, NVIDIA NIM·NeMo로 최적화한 오픈 모델 에이전트를 AI Defense로 보호할 수 있다고 적혔다. 이후 블로그는 N9100의 클라우드 파트너 참조 구조와 NX-OS 또는 SONiC 선택을 설명한다.

Hybrid Mesh Firewall을 BlueField DPU에 둔다는 후속 보도는 방향이다. 첫 포드 성공 기준에는 넣지 않고 차기 결정으로 남긴다.', 495, '[-0.045242,0.000000,-0.022621,0.000000,0.000000,0.067863,-0.022621,0.000000,-0.022621,0.045242,0.000000,0.000000,0.000000,0.101794,-0.067863,0.000000,0.000000,0.022621,0.000000,0.000000,-0.022621,0.135725,0.000000,0.000000,0.000000,0.000000,0.000000,0.033931,-0.022621,0.000000,0.000000,0.067863,0.000000,0.022621,-0.033931,0.000000,-0.079173,0.147036,-0.135725,0.000000,-0.045242,0.033931,0.000000,0.000000,0.000000,0.000000,0.000000,0.033931,0.000000,0.000000,0.000000,0.045242,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045242,0.000000,-0.022621,0.022621,0.000000,0.033931,0.000000,0.000000,-0.067863,0.000000,-0.045242,0.158346,0.000000,0.000000,-0.022621,0.000000,0.000000,0.067863,0.000000,0.000000,0.000000,0.033931,0.000000,0.067863,0.000000,0.000000,0.000000,0.000000,-0.045242,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.045242,-0.022621,0.000000,0.000000,0.022621,0.000000,0.079173,0.000000,0.045242,-0.033931,0.000000,0.000000,0.090484,0.000000,0.000000,-0.033931,0.022621,0.000000,0.067863,0.000000,0.079173,0.000000,0.045242,0.000000,0.135725,0.000000,0.033931,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045242,0.000000,-0.169657,0.022621,0.000000,0.079173,-0.033931,0.067863,-0.022621,0.101794,0.000000,0.033931,0.000000,0.000000,-0.022621,0.067863,0.000000,0.067863,0.000000,0.000000,0.000000,0.000000,0.000000,0.101794,-0.113105,0.000000,-0.067863,0.000000,0.000000,0.000000,0.000000,0.067863,0.000000,0.497660,0.000000,0.022621,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.022621,0.000000,0.000000,-0.022621,0.056552,0.000000,0.000000,0.000000,0.045242,0.000000,0.079173,0.000000,0.000000,-0.067863,0.000000,-0.067863,0.000000,-0.067863,0.000000,-0.033931,0.000000,0.000000,0.045242,-0.033931,0.045242,0.000000,0.000000,0.000000,0.000000,0.000000,0.067863,0.000000,0.022621,0.000000,0.033931,0.000000,0.022621,-0.022621,0.000000