  '6a1f505b-a8be-4fea-a086-6a30326ea6ff', 'CSCO-WX-AIM-001', 'webex-specialized-models', 'Webex AI 특화 모델과 보안 제품 LLM 적용 거버넌스', 'Governance plan for Webex specialized models and security-product LLM use',
  'reference_scenario', 'public_composite', '노이즈 제거, 가상 배경, 제스처, 책임 있는 AI 원칙은 Cisco Live와 AI 투명성 문서의 공개 설명이다. 보안 제품 LLM은 XDR 백서가 공개한 프롬프트 튜닝·전문가 평가 패턴이다. 고객 데이터로 기초 모형을 학습하는 절차는 공개되어 있지 않아 이 사례에 넣지 않았다. 일정과 금액은 협업 프로그램 계획 밴드다.', 'published', 'public',
  '글로벌 협업 환경을 Webex AI 기능으로 열 때, 기능별로 데이터가 단말에 남는지 클라우드로 가는지, 학습에 고객 내용이 쓰이는지를 먼저 구분하는 프로그램입니다. 노이즈 제거는 단말 처리로 공개되어 있고, 가상 배경은 다양한 조명·인구 집단으로 학습하며 편향을 보완했다고 Cisco Live에서 설명합니다. 제스처 인식은 동의한 내부 데이터의 모형으로 설명됩니다. 보안 제품의 LLM은 고객 내용으로 기초 모형을 다시 학습하는 일이 아니라, XDR처럼 사건 요약·보고서 초안을 위해 프롬프트를 조정하고 전문가가 평가하는 패턴으로 계획합니다.', '협업 AI를 한 번에 켜면 개인정보, 편향, 외부 LLM으로 나가는 회의 내용이 한 위험으로 섞인다. 보안 조직이 자체 LLM을 만들겠다고 하면 학습 데이터 권리와 평가 방법이 없는 프로젝트가 된다. 기능마다 데이터 흐름이 다른데 정책은 하나뿐이다.', 'Cisco는 기능별로 AI Impact Assessment, 학습 데이터 검토, 단말 처리, 보안 LLM 프록시를 공개 자료에서 구분해 설명한다. PM은 그 구분을 요구사항과 시험 항목으로 옮기면 된다. 기본값은 고객 내용으로 모형을 학습하지 않는 것이다.', '협업 생산성과 보안 운영 자동화를 한 거버넌스 위원회에서 보되, 기술 트랙은 나눈다.', '켜도 되는 기능과 추가 검토가 필요한 기능이 목록으로 남는다. 보안 LLM은 평가 셋이 있기 전에는 운영 자동 조치에 연결하지 않는다.',
  'workplace', '협업', 'enterprise', '대기업 협업·보안', 'Global', array['개인정보보호법', 'Cisco Responsible AI 원칙', 'AI Impact Assessment'],
  '5000+', 'hybrid', '단말 처리와 통제된 클라우드 LLM', '노이즈 제거는 단말. 가상 배경은 단말 추론과 로컬 사용자 이미지. 회의 요약 등 LLM은 입력·출력 가드레일과 보안 프록시를 거치며 학습에 저장하지 않는다는 공개 설명. 보안 제품 LLM은 사건 데이터에 대한 조정된 프롬프트와 사람 검토.', 'medium',
  '협업 구독과 거버넌스 프로그램의 계획 밴드입니다. 모형 학습 비용이 아닙니다.', 150000, 800000, 'M',
  4, 8, 10, 20,
  array['Cisco Webex', 'Webex AI', 'Cisco XDR'], array[]::text[], array['단말 노이즈 제거', '가상 배경', '제스처 인식', '회의 LLM 요약', '보안 사건 요약 프롬프트'], array['고객 내용 비학습 기본값', '입력·출력 가드레일', '사람 평가'], array['Webex', '웹엑스', '노이즈', 'noise', '배경', '제스처', 'gesture', 'LLM', '학습', '편향'],
  array['기능별 데이터 흐름표', '편향·음역 보완이 공개된 기능의 수용 테스트', '사용자 공지와 관리자 설정', '보안 LLM은 프롬프트 버전과 평가 셋까지'], array['고객 회의·티켓으로 기초 모형 추가 학습', '제스처 기능의 수어 통역 용도', '단말 밖에서의 제스처 모형 재사용'], array['기능별 데이터 흐름표가 승인된다', '편향·음역 수용 테스트 기록이 있다', '보안 LLM은 평가 셋 없이 자동 조치에 연결되지 않는다'], 'published', array['공개 설명: 노이즈 제거 처리는 단말에서 이루어져 해당 기능의 클라우드 전송 위험이 없다고 Cisco Live에서 설명', '공개 설명: 초기 가상 배경은 머리 모양·피부 톤·조명에서, 노이즈 제거는 높은 음역에서 성능 차이가 있어 데이터와 테스트로 보완', '공개 설명: Webex는 기본적으로 고객 내용으로 모형을 학습하지 않고, 기성 데이터·내부 데이터·합성 데이터를 쓰며 기능마다 AI Impact Assessment를 한다'],
  null, null, '2023-06-01'
);
