보안 제품의 맞춤 LLM은 별개다. XDR 백서는 사건 제목·설명·요약을 위해 조정된 프롬프트를 여러 변형으로 보내고 전문가가 유용한지 평가했으며, 같은 방식으로 보고서 초안을 만든다고 설명한다. 분석가가 초안을 고친다. 이 사례는 그 패턴을 협업 프로그램의 거버넌스와 같은 위원회에서 보게 하되, 학습 레시피나 가중치를 지어내지 않는다.', 221, '[-0.094785,0.031595,-0.126381,0.000000,-0.031595,0.000000,0.000000,0.000000,-0.031595,0.031595,-0.031595,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.031595,0.000000,0.000000,0.000000,-0.031595,0.031595,0.000000,0.078988,0.000000,0.031595,0.000000,0.047393,0.000000,0.000000,0.000000,0.063190,-0.031595,0.126381,0.000000,0.000000,-0.063190,0.000000,0.000000,0.000000,0.000000,0.126381,-0.063190,0.000000,0.000000,0.094785,0.000000,0.000000,-0.047393,0.000000,-0.094785,0.000000,0.000000,0.000000,-0.063190,0.063190,0.000000,0.031595,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.031595,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.157976,-0.063190,0.063190,0.000000,0.094785,-0.094785,0.000000,0.000000,0.063190,0.000000,0.000000,0.000000,0.189571,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.221166,0.000000,0.000000,0.000000,0.000000,0.126381,0.000000,0.189571,0.000000,0.000000,0.000000,0.047393,0.000000,0.000000,0.000000,0.000000,-0.063190,0.157976,0.000000,0.063190,-0.142178,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.063190,0.000000,0.047393,0.000000,0.126381,0.000000,0.126381,-0.031595,0.000000,0.000000,0.031595,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.031595,0.000000,0.000000,-0.031595,0.031595,0.000000,0.157976,-0.094785,0.031595,0.000000,0.000000,0.000000,0.031595,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.157976,0.000000,0.000000,0.000000,0.110583,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.063190,-0.063190,0.000000,0.000000,0.000000,0.000000,0.094785,0.000000,0.031595,0.000000,0.000000,0.000000,0.0315