insert into solution_cases (
  id, case_code, slug, title, title_en, record_type, fidelity, fidelity_note, status, confidentiality,
  executive_summary, problem_statement, opportunity, strategic_alignment, business_value,
  industry, industry_label, customer_segment, customer_segment_label, region, regulatory_context,
  company_size_band, deployment_model, deployment_model_label, architecture_pattern, complexity,
  planning_band_note, deal_size_low_usd, deal_size_high_usd, deal_size_band,
  lead_time_weeks_low, lead_time_weeks_high, duration_weeks_low, duration_weeks_high,
  cisco_solutions, partner_technologies, ai_capabilities, security_capabilities, aliases,
  scope_in, scope_out, success_criteria, outcome_type, outcomes, video_url, video_title, published_on
) values (
  'daa516ad-c6d2-44c7-a928-93832b0bc4d4', 'CSCO-SIO-DC-001', 'silicon-one-ai-fabric', 'AI-Ready 데이터센터와 Silicon One — 내부 IT의 무중단 패브릭 전환', 'Internal IT plan for an AI-ready Silicon One Ethernet fabric',
  'reference_scenario', 'public_composite', 'Silicon One, Hyperfabric AI, 400G BiDi, Unified Nexus Dashboard, Intelligent Packet Flow, Hypershield 자기 검증 업그레이드에 대한 공개 설명을 내부 IT 프로그램으로 재구성했다. 몇 주 만에 데이터센터 전체를 끝낸 고객 사례로 확인된 기록은 없다. 수 주 창은 하드웨어 도착 이후 파일럿 포드에만 쓴다.', 'published', 'public',
  '내부 네트워크·IT 팀이 기존 이더넷 데이터센터를 AI 작업이 올라갈 수 있는 패브릭으로 바꾸는 계획 시나리오입니다. 초고성능 실리콘(Silicon One), 프론트·백 네트워크를 한 운영 모델로 보는 Spectrum-X 연계, 기존 광케이블을 유지하는 400G BiDi, 통합 대시보드, 혼잡 인지 트래픽 조정이 재료입니다. 무중단은 Hypershield의 듀얼 데이터 플레인 업그레이드와, 기존 이중 멀티모드 광을 걷어내지 않는 옵틱 이행을 가리킵니다. 전체 프로그램은 16–32주, 하드웨어 도착 후 첫 파일럿 포드는 6–10주로 계획합니다.', 'AI 작업을 실험실 스위치에 올려 두면 프론트엔드 서비스 네트워크와 백엔드 GPU 네트워크의 도구, 소유자, 변경 창이 달라진다. 400G로 올리기 위해 광케이블을 교체하면 서비스 중단과 비용이 커진다. 보안 정책 변경도 유지보수 창에 몰려 패치가 늦어진다.', 'Cisco는 기존 이중 멀티모드 광을 유지한 채 400G로 가는 BiDi 옵틱을 2025년 하반기 가용으로 발표했다. 통합 Nexus Dashboard는 LAN, SAN, IPFM, AI/ML 패브릭을 한 운영 화면으로 모은다고 2025년 7월 릴리스를 목표로 발표했다. Intelligent Packet Flow는 실시간 텔레메트리로 혼잡을 보고 트래픽을 조정하며 GPU와 분산 작업까지 가시성을 확장한다고 공개되었다. Hypershield의 자기 검증 업그레이드는 섀도 경로에서 시험한 뒤 무중단으로 전환한다.', '내부 IT의 운영 표준을 AI 팀의 예외 인프라가 아니라 같은 패브릭 변경 절차로 가져온다.', '첫 AI 포드가 기존 운영 조직의 런북으로 돌아간다. 광케이블 전면 교체를 피하고, 보안 정책 변경의 시험 방법을 문서화한다. 완료 기간을 고객 사례처럼 인용하지 않는다.',
  'technology', '기술·인프라', 'internal_it', '내부 IT', 'APAC', array['변경관리', '내부 정보 보호'],
  'enterprise IT', 'on_prem', '기존 데이터센터 이행', 'Silicon One 이더넷 패브릭, 선택적 Spectrum-X 연계, NX-OS 또는 SONiC, 400G BiDi, Unified Nexus Dashboard, Intelligent Packet Flow, 보안 정책은 Hypershield 듀얼 데이터 플레인.', 'high',
  '금액은 포드와 옵틱 범위에 따른 계획 밴드다. 전체 데이터센터를 몇 주 만에 교체하는 비용이 아니다.', 1500000, 8000000, 'L',
  8, 16, 16, 32,
  array['Cisco Silicon One', 'Nexus Hyperfabric AI', 'Nexus Dashboard', 'Cisco Hypershield'], array['NVIDIA Spectrum-X'], array['AI 작업 인지 텔레메트리', '파일럿 포드'], array['무중단 정책 시험', '패브릭 세그멘테이션'], array['Silicon One', '실리콘원', '데이터센터', '무중단', '패브릭', '400G', 'Hyperfabric', '내부 IT', '몇 주'],
  array['파일럿 홀 또는 포드 1곳의 패브릭 설계', '400G 이행이 필요한 구간과 광케이블 재사용 구간 구분', '운영 대시보드 통합 범위', '보안 정책 변경의 듀얼 플레인 리허설', '하드웨어 도착 후 6–10주 파일럿 가동 계획'], array['캠퍼스 전체와 해외 사이트', '전체 데이터센터의 수 주 완료를 성공 기준으로 고정', 'GPU 클러스터 자체의 모형 학습(AI 팩토리 사례)'], array['광 실사와 이행 방식이 구간별로 적혀 있다', '파일럿 포드가 기존 런북의 변경 창으로 운영된다', '정책 변경 리허설이 무중단 절차로 남아 있다'], 'expected_planning', array['기대 결과: 첫 포드가 내부 표준 변경 절차에 편입', '공개 설계: 400G BiDi는 기존 이중 멀티모드 광을 유지', '공개 설계: Hypershield 업그레이드는 듀얼 데이터 플레인으로 중단 없이 전환'],
  null, null, '2025-06-01'
);
