insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('a1e5a17d-8cbd-487e-abf3-05055e00f4c8', 'daa516ad-c6d2-44c7-a928-93832b0bc4d4', 0, 'business_case', '비즈니스 케이스 (1)', 'case: CSCO-SIO-DC-001
title: AI-Ready 데이터센터와 Silicon One — 내부 IT의 무중단 패브릭 전환
industry: 기술·인프라 (technology)
segment: 내부 IT
solutions: Cisco Silicon One, Nexus Hyperfabric AI, Nexus Dashboard, Cisco Hypershield
partners: NVIDIA Spectrum-X
aliases: Silicon One, 실리콘원, 데이터센터, 무중단, 패브릭, 400G, Hyperfabric, 내부 IT, 몇 주
fidelity: public_composite
내부 네트워크·IT 팀이 기존 이더넷 데이터센터를 AI 작업이 올라갈 수 있는 패브릭으로 바꾸는 계획 시나리오입니다. 초고성능 실리콘(Silicon One), 프론트·백 네트워크를 한 운영 모델로 보는 Spectrum-X 연계, 기존 광케이블을 유지하는 400G BiDi, 통합 대시보드, 혼잡 인지 트래픽 조정이 재료입니다. 무중단은 Hypershield의 듀얼 데이터 플레인 업그레이드와, 기존 이중 멀티모드 광을 걷어내지 않는 옵틱 이행을 가리킵니다. 전체 프로그램은 16–32주, 하드웨어 도착 후 첫 파일럿 포드는 6–10주로 계획합니다.

문제: AI 작업을 실험실 스위치에 올려 두면 프론트엔드 서비스 네트워크와 백엔드 GPU 네트워크의 도구, 소유자, 변경 창이 달라진다. 400G로 올리기 위해 광케이블을 교체하면 서비스 중단과 비용이 커진다. 보안 정책 변경도 유지보수 창에 몰려 패치가 늦어진다.

기회: Cisco는 기존 이중 멀티모드 광을 유지한 채 400G로 가는 BiDi 옵틱을 2025년 하반기 가용으로 발표했다. 통합 Nexus Dashboard는 LAN, SAN, IPFM, AI/ML 패브릭을 한 운영 화면으로 모은다고 2025년 7월 릴리스를 목표로 발표했다. Intelligent Packet Flow는 실시간 텔레메트리로 혼잡을 보고 트래픽을 조정하며 GPU와 분산 작업까지 가시성을 확장한다고 공개되었다. Hypershield의 자기 검증 업그레이드는 섀도 경로에서 시험한 뒤 무중단으로 전환한다.

전략 정합: 내부 IT의 운영 표준을 AI 팀의 예외 인프라가 아니라 같은 패브릭 변경 절차로 가져온다.', 574, '[0.000000,0.076474,-0.015295,0.000000,0.000000,0.030590,0.000000,0.000000,-0.030590,0.015295,-0.015295,0.030590,-0.015295,0.122359,-0.030590,0.000000,0.000000,0.076474,0.000000,0.030590,0.000000,0.122359,0.000000,0.015295,0.000000,0.068827,0.000000,0.022942,-0.015295,0.045884,0.000000,0.022942,0.000000,0.015295,-0.022942,0.015295,0.000000,0.045884,-0.183538,0.030590,-0.122359,0.045884,0.000000,0.000000,0.000000,0.000000,-0.030590,0.022942,0.000000,0.015295,-0.030590,0.030590,-0.022942,0.000000,0.000000,0.000000,0.000000,0.000000,-0.061179,0.000000,-0.061179,0.000000,0.000000,0.000000,0.000000,0.076474,0.000000,0.000000,-0.122359,0.076474,-0.137653,0.000000,-0.030590,0.015295,0.000000,0.000000,-0.030590,0.015295,0.000000,0.030590,-0.015295,0.122359,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.015295,0.030590,0.000000,0.045884,-0.030590,0.122359,0.000000,0.000000,0.000000,0.061179,0.000000,0.030590,-0.015295,0.107064,0.000000,0.000000,-0.030590,0.152948,0.000000,0.030590,0.000000,0.000000,0.000000,0.122359,0.000000,0.076474,0.000000,0.000000,0.000000,0.122359,0.000000,0.022942,-0.015295,0.030590,0.000000,0.000000,0.000000,0.015295,-0.030590,0.000000,-0.091769,0.061179,0.000000,0.030590,0.000000,0.061179,0.000000,0.076474,0.000000,0.022942,0.000000,0.061179,-0.015295,0.000000,-0.061179,0.045884,0.000000,0.000000,0.000000,0.000000,-0.076474,0.168243,0.000000,0.000000,-0.068827,0.076474,0.000000,0.000000,-0.015295,0.045884,-0.038237,0.145301,-0.045884,0.061179,0.000000,0.000000,-0.015295,0.045884,0.000000,0.000000,0.000000,0.122359,0.000000,0.000000,0.000000,0.076474,-0.091769,0.030590,0.000000,0.061179,-0.076474,0.030590,-0.015295,0.015295,-0.091769,0.000000,0.000000,0.061179,0.000000,0.000000,-0.076474,0.015295,0.000000,0.000000,0.000000,0.015295,0.000000,0.030590,0.000000,0.137653,0.000000,0.000000,0.000000,0.030590,0.000000,0.045884,-0.030590,0.000000,-0.045884,0.061179,0.000000,0.122359,0