) values (
  'c0445a81-159a-4efb-a7a1-4c850784412b', 'CSCO-XDR-SOC-001', 'xdr-ai-security-operations', 'Cisco XDR — AI가 돕는 보안 운영과 디지털 회복탄력성', 'AI-assisted security operations with Cisco XDR',
  'video_demo', 'primary_source', 'CiscoKorea 영상 ‘[Digital Resilience] AI가 도와주는 보안 운영 Cisco XDR’과 XDR 백서, Instant Attack Verification 블로그, 2026년 에이전트 SOC 설명을 바탕으로 한다. 영상 속 클릭 순서를 이 기록이 재현한다고 보지 않는다. 시간 절감 비율은 공개된 보편 수치가 없어 계획 목표로 두지 않았다.', 'published', 'public',
  '보안 운영팀이 경보를 사건으로 묶고, AI로 요약을 만들고, 신뢰도가 있을 때만 플레이북을 실행하는 운영 모델입니다. Cisco XDR은 엔드포인트, 네트워크, 클라우드, 이메일, 신원 이벤트를 영향도 기준으로 묶고 LLM으로 제목·설명·요약과 보고서 초안을 만듭니다. Instant Attack Verification은 여러 에이전트가 공격을 검증해 판정과 신뢰도를 내고, 사전 플레이북을 XDR 또는 Splunk SOAR에서 돌립니다. 고영향 조치는 사람이 승인합니다. CiscoKorea 영상은 이 운영 모델을 볼 때 여는 데모입니다.', '분석가는 사건마다 여러 이벤트를 읽고 보고서를 다시 쓴다. 경보는 많고 조사는 얕아 확신이 없다. 자동 대응을 확신 없이 켜면 정상 사용자를 끊는다. 네트워크에만 보이는 횡적 이동이 엔드포인트 경보 밖에 남는다.', '공개된 XDR 능력은 상관, 우선순위, LLM 요약, 보고서 초안, 공격 검증, 포렌식, 공격 스토리보드, Talos 정보, Secure Access와의 실시간 격리를 포함한다. 자동화 활동의 AI Agent는 정한 워크플로 안에서 에이전트와 결정적 단계를 섞고 승인으로 통제한다고 제품 문서가 설명한다.', '디지털 회복탄력성은 탐지를 늘리는 일이 아니라, 사람이 검증할 판정과 실행할 플레이북을 짧게 만드는 일이다.', '분석가는 빈 보고서 대신 초안을 고치고, 낮은 확신의 경보에 자동 격리를 걸지 않는다. 측정은 파일럿 전후 같은 사건 유형의 착수 시간과 보고서 작성 시간으로 한다. 특정 퍼센트를 사전에 약속하지 않는다.',
  'cross_industry', '전 산업', 'security_operations', '보안 운영 조직', 'APAC', array['개인정보보호법', '사고 대응 절차', '변경 승인'],
  'SOC를 운영하는 조직', 'hybrid', '하이브리드 텔레메트리', 'XDR이 네트워크·엔드포인트·클라우드·이메일·신원과 Talos를 묶어 사건을 만든다. LLM은 요약과 보고서 초안. 에이전트는 검증과 저위험 조사. 플레이북은 XDR 또는 Splunk SOAR. 고영향 조치는 사람. Secure Access는 위험 사용자·기기 격리에 연결할 수 있다.', 'high',
  'XDR과 연계·플레이북 정비의 1차년도 계획 밴드입니다. 고시 가격이 아닙니다.', 400000, 1800000, 'L',
  4, 10, 12, 24,
  array['Cisco XDR', 'Cisco Talos', 'Splunk SOAR', 'Cisco Secure Access'], array['Splunk'], array['사건 요약 LLM', '보고서 초안', 'Instant Attack Verification', '트리아지 에이전트', '자연어 질의 보조'], array['교차 도메인 상관', '플레이북 대응', '사람 승인', '포렌식', '공격 스토리보드'], array['XDR', '보안 운영', 'SOC', '플레이북', '회복탄력성', '인시던트', '사건', 'Talos', '디지털 회복'],
  array['우선 사건 유형 3개의 상관과 요약', '보고서 초안 템플릿과 분석가 수정 절차', '저위험 플레이북 1개와 고영향 조치의 승인 규칙', 'CiscoKorea 데모와 공개 문서를 대조하는 운영 워크숍'], array['모든 경보의 무인 격리', '핵심 인터페이스 차단이나 계정 삭제의 완전 자동화', 'LLM이 만든 문장을 고객 통지 원문으로 바로 발송'], array['사건 유형 3개의 요약 초안을 분석가가 수정해 닫는다', '고영향 플레이북은 승인 없이 실행되지 않는다', '파일럿 전후 착수 시간을 같은 정의로 측정한다'], 'published', array['공개 설명: 상관된 사건을 LLM이 제목·설명·요약으로 만들고, 여러 프롬프트 변형 중 분석가에게 유용한 응답을 고른다', '공개 설명: 보고서 초안은 분석가가 수정한다', '공개 설명: Instant Attack Verification은 판정과 신뢰도를 만들고, 조직 절차에 따라 사람 개입 있이 또는 없이 플레이북을 호출한다', '공개 설명: 고영향 조치는 신뢰 프레임에서 사람 확인을 남긴다'],
  'https://www.youtube.com/watch?v=pYz-1Qr1AsY', '[Digital Resilience] AI가 도와주는 보안 운영 Cisco XDR', '2026-02-24'
);
